	@Test
	void minusEvaluatesRightWhenLeftIsEmpty() {
		AtomicInteger rightEvaluationCount = new AtomicInteger();
		QueryEvaluationException failure = new QueryEvaluationException("right evaluation failed");
		QueryEvaluationStep left = ignored -> new EmptyIteration<>();
		QueryEvaluationStep right = ignored -> {
			rightEvaluationCount.incrementAndGet();
			throw failure;
		};

		MinusQueryEvaluationStep step = new MinusQueryEvaluationStep(left, right);
		QueryEvaluationException actual = assertThrows(QueryEvaluationException.class, () -> {
			try (CloseableIteration<BindingSet> iteration = step.evaluate(EmptyBindingSet.getInstance())) {
				iteration.hasNext();
			}
		});

		assertSame(failure, actual);
		assertEquals(1, rightEvaluationCount.get(), "the empty-left MINUS must perform one bounded right evaluation");
	}

