	@Test
	void closingGuardedIterationClosesAnActiveRightProbe() throws Exception {
		CountDownLatch probeStarted = new CountDownLatch(1);
		CountDownLatch probeClosed = new CountDownLatch(1);
		CountDownLatch releaseProbe = new CountDownLatch(1);
		AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		QueryEvaluationStep right = ignored -> new CloseableIteration<>() {
			@Override
			public boolean hasNext() {
				probeStarted.countDown();
				try {
					releaseProbe.await(5, TimeUnit.SECONDS);
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
				}
				return false;
			}

			@Override
			public BindingSet next() {
				throw new AssertionError("the probe must remain empty");
			}

			@Override
			public void close() {
				probeClosed.countDown();
				releaseProbe.countDown();
			}
		};

		CloseableIteration<BindingSet> guarded = JoinQueryEvaluationStep.withGuaranteedRightEvaluation(right,
				EmptyBindingSet.getInstance(), ignored -> new EmptyIteration<>());
		Thread worker = new Thread(() -> {
			try {
				assertFalse(guarded.hasNext());
			} catch (Throwable failure) {
				workerFailure.set(failure);
			}
		});
		worker.start();
		assertTrue(probeStarted.await(2, TimeUnit.SECONDS), "the bounded probe must become active");

		guarded.close();

		boolean promptlyClosed = probeClosed.await(500, TimeUnit.MILLISECONDS);
		releaseProbe.countDown();
		worker.join(2_000);
		assertFalse(worker.isAlive(), "closing the wrapper must release a blocking probe");
		assertNull(workerFailure.get());
		assertTrue(promptlyClosed, "closing the wrapper must close an active bounded probe promptly");
	}

	@Test
	void interruptionWhileOpeningRightClosesReturnedProbeWithoutProbing() throws Exception {
		CountDownLatch evaluationStarted = new CountDownLatch(1);
		CountDownLatch releaseEvaluation = new CountDownLatch(1);
		CountDownLatch evaluationReturned = new CountDownLatch(1);
		AtomicInteger probeHasNextCount = new AtomicInteger();
		AtomicInteger probeCloseCount = new AtomicInteger();
		AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		QueryEvaluationStep right = ignored -> {
			evaluationStarted.countDown();
			boolean interrupted = false;
			for (;;) {
				try {
					releaseEvaluation.await();
					break;
				} catch (InterruptedException e) {
					interrupted = true;
				}
			}
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
			CloseableIteration<BindingSet> probe = new CloseableIteration<>() {
				@Override
				public boolean hasNext() {
					probeHasNextCount.incrementAndGet();
					return false;
				}

				@Override
				public BindingSet next() {
					throw new AssertionError("the interrupted probe must not be consumed");
				}

				@Override
				public void close() {
					probeCloseCount.incrementAndGet();
				}
			};
			evaluationReturned.countDown();
			return probe;
		};

		CloseableIteration<BindingSet> guarded = JoinQueryEvaluationStep.withGuaranteedRightEvaluation(right,
				EmptyBindingSet.getInstance(), ignored -> new EmptyIteration<>());
		Thread worker = new Thread(() -> {
			try {
				assertFalse(guarded.hasNext());
			} catch (Throwable failure) {
				workerFailure.set(failure);
			}
		});
		worker.start();
		try {
			assertTrue(evaluationStarted.await(2, TimeUnit.SECONDS), "right evaluation must begin");
			worker.interrupt();
			releaseEvaluation.countDown();
			assertTrue(evaluationReturned.await(2, TimeUnit.SECONDS), "right evaluation must return its probe");
			worker.join(2_000);
		} finally {
			releaseEvaluation.countDown();
			guarded.close();
			worker.interrupt();
			worker.join(2_000);
		}

		assertFalse(worker.isAlive(), "interrupting the opening thread must release it");
		assertNull(workerFailure.get());
		assertEquals(0, probeHasNextCount.get(), "an interrupted opening must close without probing");
		assertEquals(1, probeCloseCount.get(), "the returned probe must be closed exactly once");
	}

