	@Test
	void fatalOptionalProbeStripsOnlyRuntimeOptionalBindings() {
		AtomicReference<BindingSet> observedBindings = new AtomicReference<>();
		QueryEvaluationException failure = new QueryEvaluationException("right evaluation failed");
		EmptySet leftArg = new EmptySet();
		Service rightArg = new Service(Var.of("serviceRef"),
				new StatementPattern(Var.of("optionalOnly"), Var.of("predicate"), Var.of("object")), "{ }",
				java.util.Collections.emptyMap(), null, false);
		LeftJoin leftJoin = new LeftJoin(leftArg, rightArg);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(null, null) {
			@Override
			public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext context) {
				if (expr == leftArg) {
					return ignored -> new EmptyIteration<>();
				}
				if (expr == rightArg) {
					return bindings -> {
						observedBindings.set(new QueryBindingSet(bindings));
						if (bindings.hasBinding("optionalOnly")) {
							return new EmptyIteration<>();
						}
						throw failure;
					};
				}
				throw new AssertionError("unexpected precompiled expression: " + expr);
			}
		};

		QueryBindingSet entryBindings = new QueryBindingSet();
		entryBindings.addBinding("optionalOnly", org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance()
				.createIRI("urn:optional-entry"));
		entryBindings.addBinding("unrelated", org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance()
				.createIRI("urn:unrelated-entry"));
		QueryEvaluationStep step = LeftJoinQueryEvaluationStep.supply(strategy, leftJoin,
				new QueryEvaluationContext.Minimal(null));

		QueryEvaluationException actual = assertThrows(QueryEvaluationException.class, () -> {
			try (CloseableIteration<BindingSet> iteration = step.evaluate(entryBindings)) {
				iteration.hasNext();
			}
		});

		assertSame(failure, actual);
		BindingSet probeBindings = observedBindings.get();
		assertFalse(probeBindings.hasBinding("optionalOnly"));
		assertTrue(probeBindings.hasBinding("unrelated"));
	}
